import{_ as t,o as a,c as s,a6 as o}from"./chunks/framework.DtfPIzdJ.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),n={name:"guide/troubleshooting.md"};function i(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Each entry below starts with the exact symptom: the message you see in the terminal, the browser or a test report. Then it gives the cause and the fix. All messages were reproduced with Cluub 0.1.0. When a CLI command fails, set <code>CLUUB_DEBUG=1</code> to also print the stack trace.</p><h2 id="the-port-is-already-in-use" tabindex="-1">The port is already in use <a class="header-anchor" href="#the-port-is-already-in-use" aria-label="Permalink to &quot;The port is already in use&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ Port 3000 is already in use. Stop the other program or run with --port 3001.</span></span></code></pre></div><p><strong>Cause:</strong> another process (often an earlier <code>cluub dev</code> you forgot in another terminal) is listening on that port.</p><p><strong>Fix:</strong> stop it, or pick another port:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :3000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # macOS/Linux: see who holds the port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3001</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h2 id="no-cluub-project-here" tabindex="-1">&quot;No Cluub project here&quot; <a class="header-anchor" href="#no-cluub-project-here" aria-label="Permalink to &quot;&quot;No Cluub project here&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ No Cluub project here (no app.clb found). Create one with \`cluub new my-app\`.</span></span></code></pre></div><p><strong>Cause:</strong> you ran the command outside a project. Cluub looks for <code>app.clb</code> in the current folder and every parent folder.</p><p><strong>Fix:</strong> <code>cd</code> into the folder that contains <code>app.clb</code>.</p><h2 id="tabs-or-uneven-indentation-e001-e002-e003" tabindex="-1">Tabs or uneven indentation (E001, E002, E003) <a class="header-anchor" href="#tabs-or-uneven-indentation-e001-e002-e003" aria-label="Permalink to &quot;Tabs or uneven indentation (E001, E002, E003)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error E001 ui/pages/about.clb:2:1</span></span>
<span class="line"><span>  Tabs are not allowed for indentation.</span></span>
<span class="line"><span>   2 | 	view</span></span>
<span class="line"><span>     | ^</span></span>
<span class="line"><span>  hint: Use 2 spaces per level. Your editor can convert tabs to spaces (&quot;Indent using spaces&quot;).</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error E002 ui/pages/about.clb:2:1</span></span>
<span class="line"><span>  Indent each block by exactly 2 spaces (this line is indented 3 more than the line above).</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error E003 ui/pages/about.clb:4:1</span></span>
<span class="line"><span>  This line&#39;s indentation doesn&#39;t line up with any block above it.</span></span>
<span class="line"><span>  hint: Use 2 spaces to continue the outer block.</span></span></code></pre></div><p><strong>Cause:</strong> blocks are defined by indentation, exactly 2 spaces per level. Tabs are rejected outright. A line indented 3 or 4 spaces deeper than its parent is E002, and a line that returns to a column no open block uses is E003. Lexer errors stop at the first problem in each file.</p><p><strong>Fix:</strong> set your editor to &quot;indent using spaces, size 2&quot; for <code>.clb</code> files, and re-indent the file. In VS Code, use <em>Convert Indentation to Spaces</em> from the command palette. Text pasted from chat or email often brings tabs along.</p><h2 id="declaration-in-the-wrong-folder-e301" tabindex="-1">Declaration in the wrong folder (E301) <a class="header-anchor" href="#declaration-in-the-wrong-folder-e301" aria-label="Permalink to &quot;Declaration in the wrong folder (E301)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error E301 services/todo-model.clb:1:1</span></span>
<span class="line"><span>  A model belongs in the &quot;models&quot; folder, but &quot;Todo&quot; is in services/todo-model.clb.</span></span>
<span class="line"><span>  hint: Move it to models/todo.clb. Every Cluub project has the same layout so anyone can find anything.</span></span></code></pre></div><p><strong>Cause:</strong> each declaration kind has one folder: <code>models/</code>, <code>data/</code> (stores), <code>network/</code> (clients), <code>services/</code>, <code>api/</code>, <code>ui/pages/</code>, <code>ui/components/</code>, <code>ui/layouts/</code>, <code>tests/</code>. <code>app</code> goes in <code>app.clb</code> at the root.</p><p><strong>Fix:</strong> move the file to the folder the hint names. Any file name works (kebab-case is the convention): only the folder matters.</p><h2 id="layer-rule-errors-e201-e203-e204-e205" tabindex="-1">Layer rule errors (E201, E203, E204, E205) <a class="header-anchor" href="#layer-rule-errors-e201-e203-e204-e205" aria-label="Permalink to &quot;Layer rule errors (E201, E203, E204, E205)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error E201 ui/pages/about.clb:2:8</span></span>
<span class="line"><span>  A UI page (About) can&#39;t use the data layer directly (Todos is a store).</span></span>
<span class="line"><span>   2 |   uses Todos</span></span>
<span class="line"><span>     |        ^^^^^</span></span>
<span class="line"><span>  hint: Pages talk to the backend only through an \`api\`. Flow: page → api → service → store/client.</span></span></code></pre></div><p><strong>Cause:</strong> the dependency skips a layer. Allowed: page → api, api → service, service → store, client or service. Components and layouts can&#39;t <code>uses</code> anything (E203). <code>ask ai</code> (E204) and <code>env</code> (E205) are backend-only.</p><p><strong>Fix:</strong> add the missing layer. For a page that needs store data, add a service action that reads the store and an api route that calls it, then <code>uses</code> the api in the page. See <a href="/home/guide/structure">Project structure &amp; layers</a>.</p><h2 id="ai-no-api-key-or-the-ai-is-unavailable" tabindex="-1">AI: no API key or the AI is unavailable <a class="header-anchor" href="#ai-no-api-key-or-the-ai-is-unavailable" aria-label="Permalink to &quot;AI: no API key or the AI is unavailable&quot;">​</a></h2><p>Under <code>cluub start</code>, the page shows a generic toast and the server log has the reason:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>toast:       The AI service is not available right now. Please try again.</span></span>
<span class="line"><span>server log:  ✗ TodoApi.summary: No API key for claude. Run &quot;cluub ai set claude&quot; (or add ANTHROPIC_API_KEY=... to .env). Never put keys in code.</span></span></code></pre></div><p>Under <code>cluub dev</code>, the toast shows the reason directly. The templates&#39; &quot;Summarize with AI&quot; button does this until you add a key.</p><p><strong>Cause:</strong> the provider chosen for the call has no key. The provider is picked in this order: <code>using &quot;...&quot;</code> on the call, then <code>CLUUB_AI</code> (environment or <code>.env</code>), then the <code>ai</code> line in <code>app.clb</code>, then the first provider with a key, then Ollama.</p><p><strong>Fix:</strong> copy <code>.env.example</code> to <code>.env</code> and fill in the key for the provider in <code>app.clb</code> (the templates use <code>ai &quot;claude&quot;</code>), or set <code>CLUUB_AI=ollama</code> to use a local model instead. Then <strong>restart</strong> <code>cluub start</code>. <code>cluub dev</code> rebuilds by itself when <code>.env</code> changes.</p><p>A wrong key is logged with the provider&#39;s answer, for example <code>claude returned 401: invalid x-api-key. Check that your API key is correct.</code> A rate limit adds <code>You hit a rate limit; wait a moment and try again.</code></p><h2 id="ai-ollama-isn-t-running" tabindex="-1">AI: Ollama isn&#39;t running <a class="header-anchor" href="#ai-ollama-isn-t-running" aria-label="Permalink to &quot;AI: Ollama isn&#39;t running&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Could not reach Ollama at http://localhost:11434. Start it with \`ollama serve\`, or set CLUUB_AI=claude in .env.</span></span></code></pre></div><p><strong>Cause:</strong> the provider is Ollama (<code>CLUUB_AI=ollama</code>, <code>ai &quot;ollama&quot;</code>, or no key at all), and nothing answered at the address shown, which is <code>OLLAMA_HOST</code> or the default <code>http://localhost:11434</code>.</p><p><strong>Fix:</strong> start Ollama (<code>ollama serve</code>) and pull the model (<code>ollama pull llama3.2</code>, or the model named in <code>CLUUB_OLLAMA_MODEL</code>). A missing model gives <code>ollama returned 404: model &#39;name&#39; not found.</code> To use a hosted provider instead, set <code>CLUUB_AI=claude</code> (or another provider) and its key.</p><h2 id="the-page-is-blank" tabindex="-1">The page is blank <a class="header-anchor" href="#the-page-is-blank" aria-label="Permalink to &quot;The page is blank&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>A white page, and the browser console shows a module or 404 error</td><td>you opened <code>dist/public/index.html</code> from disk (<code>file://</code>), or the server isn&#39;t running</td><td>open the app through <code>cluub dev</code> or <code>cluub start</code>, at <code>http://localhost:3000</code></td></tr><tr><td>A white page with no console errors</td><td>the page&#39;s <code>view</code> is empty (warning <strong>W106</strong>), or every element sits in an <code>if</code> that is false</td><td>check <code>cluub check</code> for W106. Add something that always shows</td></tr><tr><td><code>Page not found. Nothing lives at /x.</code></td><td>no page has that path</td><td>check the <code>at &quot;/path&quot;</code> on your pages</td></tr><tr><td><code>EventSource&#39;s response has a MIME type (&quot;text/html&quot;)...</code> in the console</td><td><code>dist/</code> was last written by <code>cluub dev</code>, and you&#39;re running <code>cluub start</code></td><td>run <code>cluub build</code> before <code>cluub start</code></td></tr><tr><td><code>Refused to load ... because it violates the following Content Security Policy directive</code></td><td>your <code>theme.css</code> or view loads a font, stylesheet or script from another site</td><td>copy the file into <code>assets/</code> and reference <code>/assets/...</code></td></tr><tr><td>An old version of the app</td><td>the browser cached the static files (<code>max-age=300</code>)</td><td>hard-reload, or wait five minutes after a deploy</td></tr></tbody></table><h2 id="this-page-hit-an-error-while-drawing" tabindex="-1">&quot;This page hit an error while drawing&quot; <a class="header-anchor" href="#this-page-hit-an-error-while-drawing" aria-label="Permalink to &quot;&quot;This page hit an error while drawing&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This page hit an error while drawing: Can&#39;t turn &quot;abc&quot; into a number</span></span></code></pre></div><p><strong>Cause:</strong> an expression in the <code>view</code> threw while rendering, for example <code>text round(number(price), 2)</code> when <code>price</code> holds text, or a component given the wrong kind of value. The rest of the page (layout, header) still renders around the message.</p><p>Reading a field of something that is still <code>nothing</code> doesn&#39;t crash: views use safe member access, so <code>heading user.name</code> just shows nothing until <code>when loaded</code> fills <code>user</code>. You may still want an explicit loading state:</p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">page</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Profile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/users/{id}&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  uses</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> UserApi</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nothing</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  when</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> loaded</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> UserApi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.get(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  view</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">is</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nothing</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      spinner</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    else</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      heading</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user.name</span></span></code></pre></div><p>Runtime errors point to generated JavaScript, not to your <code>.clb</code> line (source maps are on the <a href="/home/reference/roadmap">roadmap</a>). Look at the browser console for the full error. <code>dist/public/_cluub/app.client.js</code> is readable if you need to see the generated code.</p><h2 id="a-toast-says-something-went-wrong" tabindex="-1">A toast says &quot;Something went wrong&quot; <a class="header-anchor" href="#a-toast-says-something-went-wrong" aria-label="Permalink to &quot;A toast says &quot;Something went wrong&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Toast text</th><th>Meaning</th></tr></thead><tbody><tr><td>your own message, a validation message, <code>... was not found</code></td><td>a normal Cluub error: the code did its job (<code>fail</code> messages are always shown)</td></tr><tr><td><code>Something went wrong on the server.</code></td><td>a bug in backend code under <code>cluub start</code>. The <strong>server terminal</strong> has the real message</td></tr><tr><td><code>The AI service is not available right now. Please try again.</code> / <code>An outside service is not available right now. Please try again.</code></td><td>an AI or <code>client</code> call failed under <code>cluub start</code>. The server terminal has the reason</td></tr><tr><td><code>Unexpected error in TodoApi.add: ...</code></td><td>a backend bug under <code>cluub dev</code>, with the message shown</td></tr><tr><td><code>Something went wrong: ...</code></td><td>a JavaScript error in the page&#39;s own code. Check the browser console</td></tr><tr><td><code>Request body must be valid JSON.</code> / <code>Request body is larger than 1 MB.</code></td><td>a malformed or oversized request (400 / 413)</td></tr></tbody></table><h2 id="calling-the-api-from-curl-or-another-tool-returns-415" tabindex="-1">Calling the api from curl or another tool returns 415 <a class="header-anchor" href="#calling-the-api-from-curl-or-another-tool-returns-415" aria-label="Permalink to &quot;Calling the api from curl or another tool returns 415&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;error&quot;:{&quot;code&quot;:&quot;bad_content_type&quot;,&quot;message&quot;:&quot;Send the request body as JSON with the header Content-Type: application/json.&quot;}}</span></span></code></pre></div><p><strong>Cause:</strong> api request bodies must be JSON with <code>Content-Type: application/json</code>. This is a deliberate CSRF protection (<a href="/home/guide/security#http-defaults">Security</a>). <code>curl -d</code> sends <code>application/x-www-form-urlencoded</code> by default.</p><p><strong>Fix:</strong> <code>curl -H &#39;content-type: application/json&#39; -d &#39;{&quot;title&quot;:&quot;Milk&quot;}&#39; localhost:3000/api/todos</code>.</p><h2 id="a-view-can-t-call-an-api-or-an-action-while-it-is-being-drawn-e117" tabindex="-1">&quot;A view can&#39;t call an api or an action while it is being drawn&quot; (E117) <a class="header-anchor" href="#a-view-can-t-call-an-api-or-an-action-while-it-is-being-drawn-e117" aria-label="Permalink to &quot;&quot;A view can&#39;t call an api or an action while it is being drawn&quot; (E117)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error E117 ui/pages/home.clb:5:26</span></span>
<span class="line"><span>  A view can&#39;t call an api or an action while it is being drawn.</span></span>
<span class="line"><span>   5 |     for t in TodoApi.list()</span></span>
<span class="line"><span>     |                          ^</span></span>
<span class="line"><span>  hint: Load the data into \`state\` in \`when loaded\` or in an action, then show the state in the view.</span></span></code></pre></div><p><strong>Cause:</strong> the view runs on every render. Calling an api, a page action, a component callback or <code>sleep()</code> from it would start a request on every redraw. Views only show data.</p><p><strong>Fix:</strong> declare <code>state todos = []</code>, fill it in <code>when loaded</code> (<code>todos = TodoApi.list()</code>), and write <code>for t in todos</code> in the view.</p><h2 id="generated-tests-fail" tabindex="-1">Generated tests fail <a class="header-anchor" href="#generated-tests-fail" aria-label="Permalink to &quot;Generated tests fail&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tests/generated/models.test.clb</span></span>
<span class="line"><span>  ✗ Todo: title is required 0ms</span></span>
<span class="line"><span>      It failed as expected, but with the message:</span></span>
<span class="line"><span>        &quot;Title can&#39;t be empty&quot;</span></span>
<span class="line"><span>      instead of one containing:</span></span>
<span class="line"><span>        &quot;title is required&quot;</span></span></code></pre></div><p>Generated tests are rebuilt from your code on every <code>cluub test</code>, so a failure means the code and the runtime disagree. Common causes:</p><ul><li><strong>The rule exists, but something else fires first:</strong> a <code>default</code> value or another rule that&#39;s checked earlier. Read the message to see which one.</li><li><strong>&quot;works with valid input&quot; fails with &quot;Unexpected error&quot;:</strong> the action crashed on sample input, for example by using a client result (<code>nothing</code> in tests) or the fake AI&#39;s reply as if it were real data. Handle <code>nothing</code>.</li><li><strong>&quot;the X button works&quot; fails with &quot;The page crashed&quot;:</strong> clicking with sample text in the inputs throws in the page. Run the same steps in the browser. (Buttons with a <code>disabled</code> rule get no generated test, and navigating away after the click is fine.)</li><li><strong><code>There is no input with the placeholder ...</code></strong> in your own UI test: <code>type ... into</code> matches placeholders only, not labels.</li></ul><p>Don&#39;t edit files in <code>tests/generated/</code>: the next run overwrites them. Fix the code, or write your own test in <code>tests/</code>.</p><h2 id="live-reload-doesn-t-reload" tabindex="-1">Live reload doesn&#39;t reload <a class="header-anchor" href="#live-reload-doesn-t-reload" aria-label="Permalink to &quot;Live reload doesn&#39;t reload&quot;">​</a></h2><p><strong>Symptom:</strong> <code>cluub dev</code> prints <code>✓ Rebuilt in 4.6ms</code>, but the browser keeps showing the old page.</p><p>How it works: each build has an id. When the dev server restarts, the browser&#39;s live-reload connection drops, reconnects, receives the new id, and reloads. In our test the new id arrived about 3 seconds after saving, because browsers wait a few seconds before reconnecting. So <strong>wait a moment</strong> before refreshing by hand.</p><p>If it still doesn&#39;t reload:</p><ul><li><strong>Only <code>.clb</code>, <code>.css</code> and <code>.env</code> changes are watched.</strong> Saving an image in <code>assets/</code> doesn&#39;t trigger a rebuild. Save any <code>.clb</code> file, or restart <code>cluub dev</code>.</li><li><strong>Compile errors keep the old build running.</strong> The terminal shows the errors and <code>Waiting for you to fix the errors above…</code>, and the browser keeps the last good version.</li><li><strong>You opened a production build.</strong> Live reload only exists in pages served by <code>cluub dev</code>.</li><li><strong>Linux with Node 18:</strong> <code>cluub dev</code> uses recursive <code>fs.watch</code>, which Node only supports on Linux from version 20. Use Node 20 or newer. We didn&#39;t test this on Linux.</li></ul><h2 id="the-json-store-is-corrupt-or-out-of-date" tabindex="-1">The JSON store is corrupt or out of date <a class="header-anchor" href="#the-json-store-is-corrupt-or-out-of-date" aria-label="Permalink to &quot;The JSON store is corrupt or out of date&quot;">​</a></h2><p>The server refuses to start:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ Could not load storage/todos.json for store Todos: Unexpected end of JSON input. Fix the file, or move it away to start empty.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ Could not load storage/todos.json for store Todos: done must be a yes/no value (got &quot;maybe&quot;). Fix the file, or move it away to start empty.</span></span></code></pre></div><p><strong>Causes:</strong></p><ul><li>the file was edited by hand and isn&#39;t valid JSON, or</li><li>the <strong>model changed</strong> and old records no longer pass validation. For example, you added <code>priority: text, required</code> with no default, and saved records don&#39;t have it.</li></ul><p><strong>Fix:</strong></p><ol><li>Back up the file first: <code>cp storage/todos.json storage/todos.json.bak</code>.</li><li>Repair the JSON, or update the records. Adding a default to the new field (<code>priority: text = &quot;normal&quot;</code>) is usually easiest, because loading fills in missing fields with their defaults. To start empty, move the file away.</li><li>Start the server again. Always edit store files with the server stopped: a running server overwrites the file on its next write.</li></ol><p>A leftover <code>storage/todos.json.tmp</code> is from an interrupted write. It&#39;s safe to delete.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/home/guide/errors">Errors &amp; suggestions</a></li><li><a href="/home/reference/errors">Error codes</a></li><li><a href="/home/guide/deployment">Deployment</a></li><li><a href="/home/guide/ai">AI</a></li><li><a href="/home/faq">FAQ</a></li></ul>`,75)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
